// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface RISING {
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool) external;
    function swapAndLiquifyEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x33555617F481be5973E93b432d8ecEa2D20524be;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner address
        address owner = RISING(TARGET).owner();

        // Impersonate the owner and call setSwapAndLiquifyEnabled(false)
        vm.prank(owner);
        RISING(TARGET).setSwapAndLiquifyEnabled(false);

        // Verify the exploit worked
        bool swapAndLiquifyEnabled = RISING(TARGET).swapAndLiquifyEnabled();
        assertEq(swapAndLiquifyEnabled, false, "swapAndLiquifyEnabled should be false");
        assertEq(swapAndLiquifyEnabled, false, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
